// === Tab: mySketch.js ===
const vertShader = `#ifdef GL_ES
precision highp float;
#endif
attribute vec3 aPosition;
attribute vec2 aTexCoord;
varying vec2 vTexCoord;
void main() {
  vTexCoord = aTexCoord;
  vec4 positionVec4 = vec4(aPosition, 1.0);
  positionVec4.xy = positionVec4.xy * 2.0 - 1.0;
  gl_Position = positionVec4;
}`;

const fragShader = `#ifdef GL_ES
precision highp float;
#endif
uniform vec2 iResolution;
uniform float iTime;
varying vec2 vTexCoord;

#define PI 3.14159265359
#define TAU 6.28318530718

mat2 rot2(float a) {
    float c = cos(a), s = sin(a);
    return mat2(c, -s, s, c);
}

// Serpent Palette
vec3 serpentPalette(float t) {
    vec3 a = vec3(0.6, 0.3, 0.2);
    vec3 b = vec3(0.4, 0.4, 0.3);
    vec3 c = vec3(1.2, 1.0, 0.6);
    vec3 d = vec3(0.0, 0.1, 0.4);
    return a + b * cos(TAU * (c * t + d));
}

// Data Palette
vec3 dataPalette(float t) {
    vec3 a = vec3(0.2, 0.5, 0.4);
    vec3 b = vec3(0.3, 0.4, 0.3);
    vec3 c = vec3(1.0, 1.0, 0.5);
    vec3 d = vec3(0.0, 0.33, 0.5);
    return a + b * cos(TAU * (c * t + d));
}

// Serpent Pattern
float snakePath(vec2 p, float time) {
    // multiwave
    float wave1 = sin(p.x * 3.0 + time * 2.0) * 0.3;
    float wave2 = sin(p.x * 5.0 - time * 1.5) * 0.15;
    float wave3 = sin(p.x * 8.0 + time * 3.0) * 0.08;

    float snakeY = wave1 + wave2 + wave3;

    // snake body
    float thickness = 0.08 + 0.04 * (1.0 - (p.x + 1.0) * 0.3);
    thickness *= 1.0 + 0.2 * sin(p.x * 20.0 + time * 5.0); // skin move

    return abs(p.y - snakeY) - thickness;
}

// skin texture
float snakeScales(vec2 p, float time) {
    vec2 scaleUV = p * vec2(15.0, 25.0);
    scaleUV.x += time * 3.0;

    vec2 id = floor(scaleUV);
    scaleUV = fract(scaleUV) - 0.5;
    if (mod(id.y, 2.0) > 0.5) scaleUV.x += 0.5;
    scaleUV = fract(scaleUV + 0.5) - 0.5;

    float scale = length(scaleUV * vec2(1.0, 1.5));
    return smoothstep(0.4, 0.35, scale);
}

// Circuit Pattern
float circuitPattern(vec2 p, float scale) {
    p *= scale;
    vec2 id = floor(p);
    p = fract(p) - 0.5;

    float r = fract(sin(dot(id, vec2(12.9898, 78.233))) * 43758.5453);

    // line
    float lines = 1e10;
    if (r > 0.5) {
        lines = min(lines, abs(p.x) - 0.02);
    }
    if (r > 0.3) {
        lines = min(lines, abs(p.y) - 0.02);
    }

    // node
    float node = length(p) - 0.08 * step(0.7, r);

    return min(lines, node);
}

// Bagua Pattern
float sdYinYang(vec2 p, float r) {
    float d = length(p) - r;

    // Ying Yang Half
    float half1 = length(p - vec2(0.0, r * 0.5)) - r * 0.5;
    float half2 = length(p + vec2(0.0, r * 0.5)) - r * 0.5;

    // Dot
    float dot1 = length(p - vec2(0.0, r * 0.5)) - r * 0.15;
    float dot2 = length(p + vec2(0.0, r * 0.5)) - r * 0.15;

    // Ying Yang
    float yinyang = max(d, -p.x);
    yinyang = min(yinyang, max(d, p.x));
    yinyang = min(yinyang, half1);
    yinyang = max(yinyang, -half2);

    return abs(d) - r * 0.03;
}

// Particle
float dataStream(vec2 p, float time) {
    float stream = 0.0;

    for (float i = 0.0; i < 8.0; i++) {
        float phase = i * 0.785 + time * (0.5 + i * 0.1);
        float speed = 1.0 + fract(sin(i * 45.67) * 789.0) * 2.0;

        vec2 pos = vec2(
            sin(phase) * 0.8,
            mod(time * speed + i * 0.3, 3.0) - 1.5
        );

        float trail = exp(-abs(p.x - pos.x) * 20.0);
        float head = exp(-length(p - pos) * 15.0);

        stream += (trail * 0.3 + head) * step(pos.y, p.y) * step(p.y, pos.y + 0.3);
    }

    return stream;
}

// Glitch
vec2 glitchOffset(vec2 uv, float time) {
    float glitchTime = floor(time * 8.0);
    float glitchRand = fract(sin(glitchTime * 45.23) * 12345.6);

    vec2 offset = vec2(0.0);

    if (glitchRand > 0.95) {
        float y = fract(sin(glitchTime * 12.34) * 6789.0);
        float h = 0.03;
        if (abs(uv.y - y + 0.5) < h) {
            offset.x = (fract(sin(glitchTime * 34.56) * 789.0) - 0.5) * 0.15;
        }
    }

    return offset;
}

// Scanlines
float scanlines(vec2 uv, float time) {
    float scan = sin(uv.y * 400.0 + time * 5.0) * 0.5 + 0.5;
    scan = pow(scan, 0.5) * 0.1;

    float movingScan = smoothstep(0.02, 0.0, abs(fract(uv.y + time * 0.3) - 0.5));

    return scan + movingScan * 0.1;
}

void main() {
    vec2 uv = vTexCoord * 2.0 - 1.0;
    float aspect = iResolution.x / iResolution.y;
    uv.x *= aspect;

    vec2 glitch = glitchOffset(vTexCoord, iTime);
    uv += glitch;

    vec2 uv0 = uv;
    float t = iTime;

    vec3 finalColor = vec3(0.0);

    // === Background ===
    vec3 bg = mix(
        vec3(0.02, 0.01, 0.03),
        vec3(0.01, 0.03, 0.02),
        0.5 + 0.3 * sin(t * 0.2 + uv.y * 0.5)
    );

    // bg circuit
    float circuit = circuitPattern(uv + vec2(t * 0.05, 0.0), 8.0);
    bg += vec3(0.0, 0.15, 0.1) * exp(-circuit * 30.0) * 0.3;

    finalColor = bg;

    // === bg layer1 ===
    vec2 yinYangUV = uv * rot2(t * 0.3);
    float yy = sdYinYang(yinYangUV, 0.4);
    float yyGlow = exp(-abs(yy) * 20.0);
    vec3 yyColor = mix(
        vec3(1.0, 0.8, 0.2),
        vec3(0.2, 0.8, 0.6),
        0.5 + 0.5 * sin(t + length(uv0) * 3.0)
    );
    finalColor += yyColor * yyGlow * 0.4;

    // === bg layer2 ===
    for (float i = 0.0; i < 3.0; i++) {
        vec2 snakeUV = uv * rot2(i * TAU / 3.0 + t * 0.2);
        snakeUV.x += sin(t * 0.5 + i) * 0.2;

        float snake = snakePath(snakeUV, t + i);
        float snakeGlow = exp(-max(snake, 0.0) * 30.0);

        float scales = snakeScales(snakeUV, t);

        vec3 snakeColor = serpentPalette(i * 0.33 + t * 0.1);
        snakeColor = mix(snakeColor, snakeColor * 1.5, scales * snakeGlow);

        vec2 eyePos = vec2(0.8 + sin(t * 0.5 + i) * 0.2, 
                          sin(0.8 * 3.0 + t * 2.0) * 0.3 + 
                          sin(0.8 * 5.0 - t * 1.5) * 0.15);
        eyePos = eyePos * rot2(i * TAU / 3.0 + t * 0.2);
        float eye = length(uv - eyePos);
        float eyeGlow = exp(-eye * 40.0);

        finalColor += snakeColor * snakeGlow * 0.6;
        finalColor += vec3(1.0, 0.3, 0.1) * eyeGlow * 1.5;
    }

    // === bg layer3 ===
    float data = dataStream(uv, t);
    vec3 dataColor = dataPalette(t * 0.2);
    finalColor += dataColor * data * 0.8;

    // === bg layer4 ===
    float ripple = sin(length(uv) * 15.0 - t * 4.0);
    ripple = smoothstep(0.0, 0.3, ripple) * exp(-length(uv) * 1.5);
    vec3 rippleColor = mix(
        vec3(0.8, 0.2, 0.3),
        vec3(0.2, 0.6, 0.8),
        0.5 + 0.5 * sin(length(uv) * 5.0 + t)
    );
    finalColor += rippleColor * ripple * 0.3;

    // === bg layer5 ===
    for (float i = 0.0; i < 6.0; i++) {
        float angle = i * TAU / 6.0 + t * 0.15;
        float radius = 0.5 + 0.1 * sin(t + i * 2.0);
        vec2 runePos = vec2(cos(angle), sin(angle)) * radius;

        vec2 runeUV = (uv - runePos) * 10.0;
        float line1 = smoothstep(0.1, 0.0, abs(runeUV.y - 0.3)) * step(abs(runeUV.x), 0.4);
        float line2 = smoothstep(0.1, 0.0, abs(runeUV.y)) * step(abs(runeUV.x), 0.4);
        float line3 = smoothstep(0.1, 0.0, abs(runeUV.y + 0.3)) * step(abs(runeUV.x), 0.4);

        if (mod(i, 2.0) < 0.5) {
            line2 *= step(0.1, abs(runeUV.x));
        }

        float rune = (line1 + line2 + line3) * exp(-length(uv - runePos) * 5.0);
        vec3 runeColor = vec3(1.0, 0.85, 0.4);
        finalColor += runeColor * rune * 0.4;
    }

    // === bg layer6 ===
    float centerGlow = exp(-length(uv) * 2.5);
    vec3 neonCenter = mix(
        vec3(1.0, 0.2, 0.3),
        vec3(0.0, 0.8, 0.5),
        0.5 + 0.5 * sin(t * 2.0)
    );
    finalColor += neonCenter * centerGlow * 0.25;

    // === Post Process ===

    float chromaShift = 0.006 * (1.0 + 0.5 * sin(t * 3.0 + uv.y * 5.0));
    vec2 uvR = uv + vec2(chromaShift, 0.0);
    vec2 uvB = uv - vec2(chromaShift, 0.0);

    float snakeR = snakePath(uvR * rot2(t * 0.2), t);
    float snakeB = snakePath(uvB * rot2(t * 0.2), t);
    finalColor.r += exp(-max(snakeR, 0.0) * 30.0) * 0.15;
    finalColor.b += exp(-max(snakeB, 0.0) * 30.0) * 0.15;

    float scan = scanlines(vTexCoord, t);
    finalColor *= 1.0 - scan;

    float vignette = 1.0 - length(uv0) * 0.35;
    vignette = smoothstep(0.0, 1.0, vignette);
    finalColor *= vignette;

    finalColor.r *= 1.08;
    finalColor.g *= 0.95;

    float noise = fract(sin(dot(vTexCoord + t, vec2(12.9898, 78.233))) * 43758.5453);
    finalColor += (noise - 0.5) * 0.05;

    float bloom = smoothstep(0.85, 1.2, length(finalColor));
    finalColor += vec3(1.0, 0.9, 0.7) * bloom * 0.15;

    float gray = dot(finalColor, vec3(0.299, 0.587, 0.114));
    finalColor = mix(finalColor, vec3(gray) * vec3(1.1, 1.0, 0.95), 0.08);

    finalColor = pow(clamp(finalColor, 0.0, 1.0), vec3(0.92));

    gl_FragColor = vec4(finalColor, 1.0);
}`;

let theShader;

function setup() {
  createCanvas(windowWidth, windowHeight, WEBGL);
  pixelDensity(1);
  noStroke();
  theShader = createShader(vertShader, fragShader);
}

function draw() {
  shader(theShader);
  theShader.setUniform("iResolution", [width, height]);
  theShader.setUniform("iTime", millis() / 1000.0);
  rect(-width / 2, -height / 2, width, height);
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}

