/* === 4K MV Pure Canvas - 全域控制項與 UI 面板隱藏 === */
.dg, .lil-gui, .qs_main, .opc-control, #opc-control-panel, .control-panel, .gui-container,
[class*='gui'], [id*='gui'], [class*='control'], [id*='control'],
[class*='instruction'], [id*='instruction'], [class*='info'], [id*='info'],
[class*='fps'], [id*='fps'], [class*='overlay'], [id*='overlay'],
input, button, select, textarea, label, form {
  display: none !important;
  visibility: hidden !important;
  opacity: 0 !important;
  pointer-events: none !important;
}
@import url('https://fonts.googleapis.com/css2?family=Ma+Shan+Zheng&family=ZCOOL+QingKe+HuangYou&display=swap');

* { margin: 0; padding: 0; box-sizing: border-box; }

body { 
  overflow: hidden; 
  background: #0a0508;
  font-family: "Ma Shan Zheng", "ZCOOL QingKe HuangYou", serif;
}

canvas { 
  display: block; 
}

.overlay {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
  z-index: 10;
}

.title-container {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  text-align: center;
}

.year {
  font-family: 'ZCOOL QingKe HuangYou', sans-serif;
  font-size: clamp(1rem, 3vw, 1.5rem);
  color: #00ff88;
  text-shadow: 0 0 20px #00ff88;
  letter-spacing: 1em;
  margin-bottom: 0.5rem;
  animation: dataStream 2s infinite;
  opacity: 0.8;
}

.title {
  font-size: clamp(3rem, 12vw, 10rem);
  color: transparent;
  background: linear-gradient(
    180deg,
    #ffd700 0%,
    #ff6b35 30%,
    #ff0844 60%,
    #8b0000 100%
  );
  -webkit-background-clip: text;
  background-clip: text;
  filter: drop-shadow(0 0 10px #ff0844) drop-shadow(0 0 40px #ff6b35);
  animation: serpentPulse 3s ease-in-out infinite;
  line-height: 1;
}

.subtitle {
  font-family: 'ZCOOL QingKe HuangYou', sans-serif;
  font-size: clamp(0.6rem, 1.5vw, 1rem);
  color: #00ffff;
  text-shadow: 0 0 10px #00ffff, 0 0 30px #0088ff;
  letter-spacing: 0.5em;
  margin-top: 1rem;
  opacity: 0.7;
  animation: glitchText 4s infinite;
}

@keyframes serpentPulse {
  0%, 100% { 
    filter: drop-shadow(0 0 10px #ff0844) drop-shadow(0 0 40px #ff6b35);
    transform: scale(1);
  }
  50% { 
    filter: drop-shadow(0 0 20px #ff0844) drop-shadow(0 0 60px #ffd700);
    transform: scale(1.02);
  }
}

@keyframes dataStream {
  0%, 100% { opacity: 0.8; }
  50% { opacity: 0.4; }
}

@keyframes glitchText {
  0%, 100% { transform: translateX(0); opacity: 0.7; }
  92% { transform: translateX(0); opacity: 0.7; }
  93% { transform: translateX(-5px); opacity: 0.3; }
  94% { transform: translateX(5px); opacity: 0.9; }
  95% { transform: translateX(-3px); opacity: 0.5; }
  96% { transform: translateX(0); opacity: 0.7; }
}

.scanlines {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: repeating-linear-gradient(
    0deg,
    transparent,
    transparent 2px,
    rgba(0, 0, 0, 0.1) 2px,
    rgba(0, 0, 0, 0.1) 4px
  );
  pointer-events: none;
  z-index: 20;
}

.data-rain {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
  z-index: 5;
  opacity: 0.15;
  background: 
    linear-gradient(180deg, 
      transparent 0%,
      rgba(0, 255, 136, 0.1) 50%,
      transparent 100%
    );
  animation: rain 1s linear infinite;
}

@keyframes rain {
  0% { background-position: 0 -100vh; }
  100% { background-position: 0 100vh; }
}

/* Bagua Symbol */
.bagua {
  position: fixed;
  font-size: 1.5rem;
  color: rgba(255, 215, 0, 0.2);
  z-index: 25;
  pointer-events: none;
  animation: float 6s ease-in-out infinite;
}

.bagua:nth-child(1) { top: 10%; left: 5%; animation-delay: 0s; }
.bagua:nth-child(2) { top: 20%; right: 8%; animation-delay: 1s; }
.bagua:nth-child(3) { bottom: 15%; left: 10%; animation-delay: 2s; }
.bagua:nth-child(4) { bottom: 25%; right: 5%; animation-delay: 3s; }

@keyframes float {
  0%, 100% { transform: translateY(0) rotate(0deg); opacity: 0.2; }
  50% { transform: translateY(-20px) rotate(180deg); opacity: 0.4; }
}

.corner {
  position: fixed;
  width: 60px;
  height: 60px;
  z-index: 25;
  pointer-events: none;
  opacity: 0.5;
}

.corner svg {
  width: 100%;
  height: 100%;
}

.corner.tl { top: 15px; left: 15px; }
.corner.tr { top: 15px; right: 15px; transform: scaleX(-1); }
.corner.bl { bottom: 15px; left: 15px; transform: scaleY(-1); }
.corner.br { bottom: 15px; right: 15px; transform: scale(-1, -1); }
